import sys

def main():
    data = sys.stdin.read().split()
    p = 0
    m = int(data[p]); p += 1
    lists = []
    for _ in range(m):
        k = int(data[p]); p += 1
        lists.append([int(x) for x in data[p:p + k]])
        p += k
    q = int(data[p]); p += 1
    i = j = 0
    last = None
    out = []
    for _ in range(q):
        op = data[p]; p += 1
        while i < m and j >= len(lists[i]):
            i += 1
            j = 0
        if op == 'hasNext':
            out.append('true' if i < m else 'false')
        elif op == 'next':
            if i >= m:
                last = None
                out.append('-1')
            else:
                out.append(str(lists[i][j]))
                last = (i, j)
                j += 1
        else:
            if last is None:
                out.append('-1')
            else:
                a, b = last
                out.append(str(lists[a][b]))
                del lists[a][b]
                if a == i:
                    j -= 1
                last = None
    for l in lists:
        out.append('[' + ','.join(map(str, l)) + ']')
    print('\n'.join(out))

main()

