    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.resetSyntax();
        in.wordChars(33, 255);
        in.whitespaceChars(0, 32);
        in.nextToken();
        int m = Integer.parseInt(in.sval);
        List<List<Long>> lists = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            in.nextToken();
            int k = Integer.parseInt(in.sval);
            List<Long> l = new ArrayList<>();
            for (int j = 0; j < k; j++) {
                in.nextToken();
                l.add(Long.parseLong(in.sval));
            }
            lists.add(l);
        }
        in.nextToken();
        int q = Integer.parseInt(in.sval);
        NestedIterator it = new NestedIterator(lists);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            in.nextToken();
            String op = in.sval;
            if (op.equals("hasNext")) sb.append(it.hasNext() ? "true" : "false").append("\n");
            else if (op.equals("next")) sb.append(it.next()).append("\n");
            else sb.append(it.remove()).append("\n");
        }
        for (List<Long> l : it.remaining()) {
            sb.append("[");
            for (int j = 0; j < l.size(); j++) sb.append(j > 0 ? "," : "").append(l.get(j));
            sb.append("]\n");
        }
        System.out.print(sb);
    }
}
